<script lang="ts">import {enhance} from '$app/forms';import type {PageData,ActionData} from './$types';import Icon from '$lib/components/Icon.svelte';export let data:PageData;export let form:ActionData;</script>
<svelte:head><title>Categorias — FRAME</title></svelte:head><div class="admin-heading"><div><h1>Categorias</h1><p>Organize sua coleção pelas especialidades que fazem sentido para você.</p></div></div>{#if form?.error}<div class="alert" role="alert">{form.error}</div>{:else if form?.success}<div class="alert success" role="status">{form.success}</div>{/if}<section class="panel"><div class="panel-title"><h2>Adicionar categoria</h2></div><form method="POST" action="?/save" use:enhance><div class="form-grid"><div class="field"><label for="new-name">Nome</label><input name="name" id="new-name" required maxlength="100" placeholder="Motion design"/></div><div class="field"><label for="new-slug">Endereço</label><input name="slug" id="new-slug" required pattern="[a-z0-9]+(-[a-z0-9]+)*" placeholder="motion-design"/></div><div class="field"><label for="new-order">Ordem</label><input id="new-order" name="sortOrder" type="number" min="0" max="10000" value={data.categories.length}/></div></div><div class="form-actions"><button class="btn small accent"><Icon name="plus" size={14}/> Adicionar categoria</button></div></form></section>{#each data.categories as category}<section class="panel category-row"><form method="POST" action="?/save" use:enhance><input type="hidden" name="id" value={category.id}/><div class="form-grid"><div class="field"><label for={`name-${category.id}`}>Nome</label><input id={`name-${category.id}`} name="name" value={category.name} required maxlength="100"/></div><div class="field"><label for={`slug-${category.id}`}>Endereço</label><input id={`slug-${category.id}`} name="slug" value={category.slug} required pattern="[a-z0-9]+(-[a-z0-9]+)*"/></div><div class="field"><label for={`order-${category.id}`}>Ordem</label><input id={`order-${category.id}`} name="sortOrder" type="number" min="0" max="10000" value={category.sortOrder}/></div></div><div class="form-actions"><button class="btn small secondary">Salvar categoria</button><button class="btn small secondary" f